import{domain,rules,presets,analyze,validate}from './rules-core.mjs';
const $=id=>document.getElementById(id),labels=Object.fromEntries(rules.map(r=>[r.id,r.label]));
const formulas={square:'Penalty: (x² − 4)²',positive:'Penalty: max(0, 1 − x)²',negative:'Penalty: max(0, x + 1)²',three:'Penalty: (x − 3)²'};
for(const r of rules){const d=document.createElement('div');d.className='rule-control';d.innerHTML=`<label class="toggle"><input id="${r.id}" type="checkbox">${r.label}</label><label class="weight-label" for="${r.id}Weight">Soft weight <output id="${r.id}Value">1</output></label><input id="${r.id}Weight" type="range" min="0" max="10" step="1" value="1"><small>${formulas[r.id]}</small>`;$('ruleControls').append(d);}
for(const x of domain){const o=document.createElement('option');o.value=x;o.textContent=x;$('candidate').append(o);}$('candidate').value=2;
function config(){return{active:rules.filter(r=>$(r.id).checked).map(r=>r.id),weights:Object.fromEntries(rules.map(r=>[r.id,+$(r.id+'Weight').value])),candidate:+$('candidate').value};}
const values=xs=>xs.length?xs.join(', '):'None';
function render(){const c=config(),a=analyze(c);for(const r of rules){$(r.id+'Value').value=c.weights[r.id];$(r.id+'Weight').disabled=!c.active.includes(r.id);}for(const b of document.querySelectorAll('[data-preset]'))b.setAttribute('aria-pressed',String(presets[b.dataset.preset].length===c.active.length&&presets[b.dataset.preset].every(id=>c.active.includes(id))));$('resultStatus').textContent=a.status;$('resultSummary').textContent=`${a.feasible.length} of 9 candidates satisfy all ${c.active.length} active rules. ${a.feasible.length===1?'The rulebook determines an answer here; the observation checks whether it is the right one.':a.feasible.length?'The rules leave more than one possible answer.':'There is no answer that follows this rulebook.'}`;
$('candidates').replaceChildren();for(const p of a.scores){const d=document.createElement('div');d.className='candidate'+(a.feasible.includes(p.x)?' valid':'')+(a.soft.includes(p.x)?' best':'');d.innerHTML=`<small class="truth">${p.x===2?'★':' '}</small><b>${p.x}</b><small>loss ${p.score}</small><small>${a.feasible.includes(p.x)?'valid':'fails'}</small>`;$('candidates').append(d);}
$('softAnswers').textContent=values(a.soft);$('softSummary').textContent=`Minimum weighted penalty: ${a.min}. ${a.soft.every(x=>a.feasible.includes(x))?'All minimizers satisfy the active rules.':'At least one minimizer violates an active rule.'} A zero-weight rule still applies in the exact checker.`;$('hardAnswers').textContent=values(a.feasible);$('hardSummary').textContent=a.feasible.length===1?'Exactly one answer in the declared domain. This does not establish that the rulebook describes reality.':a.feasible.length?'All satisfying answers are retained; no arbitrary choice is presented as a conclusion.':'No satisfying answer. The lab refuses to choose a compromise and call it valid.';
$('conflictSummary').hidden=!a.conflicts.length;$('conflictSummary').textContent='Minimal conflicting rule sets: '+a.conflicts.map(s=>s.map(id=>labels[id]).join(' + ')).join('; ')+'. Each set already has no solution in the declared domain.';$('checks').replaceChildren();for(const row of a.checks){const li=document.createElement('li');li.className=row.pass?'pass':'fail';li.textContent=`${row.pass?'Pass':'Fail'} · ${labels[row.id]}`;$('checks').append(li);}$('verificationSummary').textContent=c.active.length?(a.checks.every(r=>r.pass)?'All active rules pass.':'This candidate violates the rulebook.'):'No active rules: every domain candidate passes vacuously.';$('observationSummary').className=a.observationMatches?'pass':'fail';$('observationSummary').textContent=a.observationMatches?'Observation check: agrees with synthetic x = +2.':'Observation check: disagrees with synthetic x = +2. Rule consistency alone cannot establish empirical truth.';return a;}
function apply(c){validate(c);for(const r of rules){$(r.id).checked=c.active.includes(r.id);$(r.id+'Weight').value=c.weights[r.id];}$('candidate').value=c.candidate;return render();}
for(const b of document.querySelectorAll('[data-preset]'))b.onclick=()=>{const p=b.dataset.preset;apply({active:presets[p],weights:Object.fromEntries(rules.map(r=>[r.id,1])),candidate:p==='wrong'?-2:p==='conflict'?3:2});};$('ruleControls').oninput=render;$('candidate').onchange=render;apply({active:presets.determined,weights:Object.fromEntries(rules.map(r=>[r.id,1])),candidate:2});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'explore_rulebook',title:'Explore Rule Lab',description:'Set the visible toy integer rules and weights, then enumerate candidates and independently check a proposed answer.',inputSchema:{type:'object',properties:{active:{type:'array',items:{type:'string',enum:rules.map(r=>r.id)},uniqueItems:true},weights:{type:'object',properties:Object.fromEntries(rules.map(r=>[r.id,{type:'integer',minimum:0,maximum:10}])),required:rules.map(r=>r.id),additionalProperties:false},candidate:{type:'integer',minimum:-4,maximum:4}},required:['active','weights','candidate'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async c=>apply(c)},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
